package dk.stream.android;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import androidx.media3.common.Player;
import java.util.*;

/** Holds the original playback source while Android's chooser hands it to another player. */
@androidx.media3.common.util.UnstableApi
public final class ExternalPlaybackActivity extends androidx.appcompat.app.AppCompatActivity {
 private final ExternalPlaybackReturn returning=new ExternalPlaybackReturn();private final Handler handler=new Handler(Looper.getMainLooper());
 private String sessionToken;private android.widget.TextView status;
 private final Runnable returned=new Runnable(){public void run(){if(!returning.canResume(hasWindowFocus())||isFinishing())return;if(BluetoothOutputButton.streamPlaying()){resumeStream();return;}boolean externalAudio=((android.media.AudioManager)getSystemService(AUDIO_SERVICE)).isMusicActive();if(externalAudio){status.setText("Afspilningen er åbnet i "+getIntent().getStringExtra("externalLabel")+".\nDu kan fortsætte her, når du vil tilbage til Stream.");handler.postDelayed(this,1000);}else resumeStream();}};
 static boolean available(Context context){return ExternalOutputState.active()||CastPlayback.hasMedia(context)&&!CastPlayback.image(context)||LocalAudioService.current()!=null&&!LocalAudioService.current().image()&&(LocalAudioService.player()==null||LocalAudioService.player().getPlaybackState()!=Player.STATE_ENDED)||RadioPlaybackService.selectedStation()!=null||RadioPlaybackService.selectedFile()!=null&&RadioPlaybackService.audioPlayer()!=null&&RadioPlaybackService.audioPlayer().getPlaybackState()!=Player.STATE_ENDED;}
 static void open(Context context){
  if(TvRecordingService.active()){android.widget.Toast.makeText(context,"Stop optagelsen, før du åbner en anden afspiller.",android.widget.Toast.LENGTH_SHORT).show();return;}
  Intent intent=new Intent(context,ExternalPlaybackActivity.class);
  try{
   if(CastPlayback.hasMedia(context)&&!CastPlayback.image(context)){var remote=CastPlayback.remote(context);var info=remote.getMediaInfo();intent.putExtra("source","cast").putExtra("castInfo",info).putExtra("family",CastPlayback.audio(context)?"audio":"video").putExtra("live",info.getStreamType()==com.google.android.gms.cast.MediaInfo.STREAM_TYPE_LIVE).putExtra("uri",info.getContentId()).putExtra("mime",info.getContentType()).putExtra("name",CastPlayback.title(context)).putExtra("position",info.getStreamType()==com.google.android.gms.cast.MediaInfo.STREAM_TYPE_LIVE?0:remote.getApproximateStreamPosition());}
   else if(LocalAudioService.current()!=null&&!LocalAudioService.current().image()){LocalMedia file=LocalAudioService.current();intent.putExtra("source","local").putExtra("family",file.audio()?"audio":"video").putExtra("uri",file.uri).putExtra("name",file.name).putExtra("mime",CastPlayback.mime(file)).putExtra("position",LocalAudioService.player()==null?0:Math.max(0,LocalAudioService.player().getCurrentPosition()));}
   else if(RadioPlaybackService.selectedFile()!=null){LocalMedia file=RadioPlaybackService.selectedFile();intent.putExtra("source","carfile").putExtra("family","audio").putExtra("uri",file.uri).putExtra("name",file.name).putExtra("mime",CastPlayback.mime(file)).putExtra("position",RadioPlaybackService.audioPlayer().getCurrentPosition());}
   else{RadioStation station=RadioPlaybackService.selectedStation();if(station==null)return;intent.putExtra("source","radio").putExtra("family","audio").putExtra("radio",station.toJson().toString()).putExtra("uri",station.url).putExtra("name",station.displayName()).putExtra("mime",station.hls?"application/vnd.apple.mpegurl":"audio/*");}
   context.startActivity(intent);
  }catch(Exception error){android.widget.Toast.makeText(context,"Indholdet kunne ikke åbnes i en anden app.",android.widget.Toast.LENGTH_LONG).show();}
 }
 static void openVideo(MainActivity activity,Playlist.Channel channel,Player player){
  Intent intent=new Intent(activity,ExternalPlaybackActivity.class).putExtra("source","video").putExtra("externalToken",UUID.randomUUID().toString()).putExtra("stopCastOnHandoff",CastPlayback.hasMedia(activity)).putExtra("sourceStopped",player!=null).putExtra("family","video").putExtra("uri",channel.url).putExtra("name",channel.name).putExtra("kind",channel.kind.name()).putExtra("logo",channel.logoUrl).putExtra("mime",ExternalPlaybackType.mime(channel.url,"video/*")).putExtra("position",channel.kind==Playlist.Kind.TV||player==null?0:Math.max(0,player.getCurrentPosition()));
  ExternalOutputState.begin(intent.getStringExtra("externalToken"));RadioPlaybackService.stopForSourceSwitch(activity);LocalAudioService.stopForSourceSwitch(activity);if(player!=null){PlaybackTracker.flushAll();player.pause();player.stop();}try{activity.startActivity(intent);}catch(RuntimeException failure){ExternalOutputState.end(intent.getStringExtra("externalToken"));if(player!=null){player.prepare();player.play();}android.widget.Toast.makeText(activity,"Indholdet kunne ikke åbnes i en anden app.",android.widget.Toast.LENGTH_LONG).show();}
 }
 @Override public void onCreate(Bundle saved){super.onCreate(saved);sessionToken=getIntent().getStringExtra("externalToken");if(sessionToken==null){sessionToken=UUID.randomUUID().toString();getIntent().putExtra("externalToken",sessionToken);}ExternalOutputState.begin(sessionToken);getSharedPreferences("external_player",0).edit().clear().apply();android.widget.LinearLayout root=new android.widget.LinearLayout(this);root.setOrientation(android.widget.LinearLayout.VERTICAL);root.setGravity(android.view.Gravity.CENTER);root.setPadding(32,32,32,32);status=new android.widget.TextView(this);status.setText("Vælg en afspiller …");status.setGravity(android.view.Gravity.CENTER);root.addView(status);android.widget.Button resume=new android.widget.Button(this);resume.setText("Fortsæt i Stream");resume.setOnClickListener(view->resumeStream());root.addView(resume);setContentView(root);if(saved!=null){returning.launched=saved.getBoolean("launched");returning.left=saved.getBoolean("left");if(returning.launched)ExternalOutputState.choose(sessionToken,getIntent().getStringExtra("externalPackage"),getPackageName());}getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){public void handleOnBackPressed(){resumeStream();}});if(!returning.launched)handler.post(this::launch);}
 private static final class Choice {final android.content.pm.ResolveInfo app;final Intent intent;Choice(android.content.pm.ResolveInfo app,Intent intent){this.app=app;this.intent=intent;}}
 private void pauseSource(Runnable ready){getIntent().putExtra("sourceStopped",true);PlaybackTracker.flushAll();String source=getIntent().getStringExtra("source");Player player="local".equals(source)?LocalAudioService.player():"radio".equals(source)||"carfile".equals(source)?RadioPlaybackService.audioPlayer():null;if(player!=null){if(!"radio".equals(source))getIntent().putExtra("position",Math.max(0,player.getCurrentPosition()));getIntent().putExtra("sourceStopped",true);player.pause();player.stop();}if(("cast".equals(source)||getIntent().getBooleanExtra("stopCastOnHandoff",false))&&CastPlayback.remote(this)!=null){if("cast".equals(source)&&!getIntent().getBooleanExtra("live",false))getIntent().putExtra("position",CastPlayback.remote(this).getApproximateStreamPosition());getIntent().putExtra("sourceStopped",true);CastPlayback.remote(this).stop().setResultCallback(result->{if(isFinishing()||returning.finished)return;if(result.getStatus().isSuccess())ready.run();else{android.widget.Toast.makeText(this,"Casting kunne ikke standses før overdragelsen.",android.widget.Toast.LENGTH_LONG).show();resumeStream();}});}else ready.run();}

 private void launch(){if(isFinishing()||returning.finished)return;Intent target=getIntent();String value=target.getStringExtra("uri");if(value==null){resumeStream();return;}try{
   Uri uri=value.startsWith("content:")?ExternalMediaProvider.share(this,new LocalMedia(value,target.getStringExtra("name"),target.getStringExtra("mime"),false)):Uri.parse(Playlist.httpUrl(value).toString());String mime=ExternalPlaybackType.mime(value,target.getStringExtra("name"),target.getStringExtra("mime"));java.util.Map<String,Choice> apps=new LinkedHashMap<>();
   for(String type:ExternalPlaybackType.candidates(mime,target.getStringExtra("family"))){Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,type).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra(Intent.EXTRA_TITLE,target.getStringExtra("name")).putExtra("title",target.getStringExtra("name")).putExtra(Intent.EXTRA_STREAM,uri).putExtra("position",(int)Math.min(Integer.MAX_VALUE,Math.max(0,target.getLongExtra("position",0)))).putExtra("return_result",true);if("content".equals(uri.getScheme()))view.setClipData(ClipData.newRawUri("Afspilning",uri));for(android.content.pm.ResolveInfo app:getPackageManager().queryIntentActivities(view,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY)){if(app.activityInfo==null||!app.activityInfo.exported||getPackageName().equals(app.activityInfo.packageName)||apps.containsKey(app.activityInfo.packageName))continue;Intent explicit=new Intent(view).setComponent(new ComponentName(app.activityInfo.packageName,app.activityInfo.name));apps.put(app.activityInfo.packageName,new Choice(app,explicit));}}
   if(apps.isEmpty())throw new ActivityNotFoundException();List<Choice> choices=new ArrayList<>(apps.values());Collections.sort(choices,(one,two)->String.valueOf(one.app.loadLabel(getPackageManager())).compareToIgnoreCase(String.valueOf(two.app.loadLabel(getPackageManager()))));android.widget.ArrayAdapter<Choice> adapter=new android.widget.ArrayAdapter<Choice>(this,android.R.layout.simple_list_item_1,choices){@Override public android.view.View getView(int position,android.view.View recycled,android.view.ViewGroup parent){android.widget.TextView row=(android.widget.TextView)super.getView(position,recycled,parent);Choice choice=getItem(position);row.setText(choice.app.loadLabel(getPackageManager()));android.graphics.drawable.Drawable icon=choice.app.loadIcon(getPackageManager());int size=Math.round(32*getResources().getDisplayMetrics().density);icon.setBounds(0,0,size,size);row.setCompoundDrawables(icon,null,null,null);row.setCompoundDrawablePadding(Math.round(12*getResources().getDisplayMetrics().density));row.setMinHeight(Math.round(56*getResources().getDisplayMetrics().density));return row;}};
   new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Åbn i anden afspilningsapp").setAdapter(adapter,(dialog,index)->{Choice choice=choices.get(index);try{pauseSource(()->{if(returning.finished||isFinishing())return;getIntent().putExtra("externalPackage",choice.app.activityInfo.packageName).putExtra("externalLabel",String.valueOf(choice.app.loadLabel(getPackageManager())));ExternalOutputState.choose(sessionToken,choice.app.activityInfo.packageName,getPackageName());returning.launched=true;try{choice.intent.putExtra("position",(int)Math.min(Integer.MAX_VALUE,Math.max(0,getIntent().getLongExtra("position",0))));if(choice.app.activityInfo.launchMode>android.content.pm.ActivityInfo.LAUNCH_SINGLE_TOP){startActivity(new Intent(choice.intent).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}else startActivityForResult(choice.intent,7400);}catch(RuntimeException failed){android.widget.Toast.makeText(this,"Afspilleren kunne ikke åbne indholdet.",android.widget.Toast.LENGTH_LONG).show();resumeStream();}});}catch(RuntimeException failure){android.widget.Toast.makeText(this,"Afspilleren kunne ikke åbne indholdet.",android.widget.Toast.LENGTH_LONG).show();resumeStream();}}).setNegativeButton("Annuller",(dialog,which)->resumeStream()).setOnCancelListener(dialog->resumeStream()).show();
  }catch(Exception error){android.widget.Toast.makeText(this,"Ingen tilgængelig app kunne åbne afspilningen.",android.widget.Toast.LENGTH_LONG).show();resumeStream();}}
 @Override protected void onPause(){returning.paused();handler.removeCallbacks(returned);super.onPause();}
 @Override protected void onStop(){returning.covered();handler.removeCallbacks(returned);super.onStop();}
 @Override protected void onResume(){super.onResume();returning.foreground=true;scheduleReturn();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)scheduleReturn();else handler.removeCallbacks(returned);}
 private void scheduleReturn(){handler.removeCallbacks(returned);if(returning.launched&&returning.left)handler.postDelayed(returned,400);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==7400){if(result==RESULT_OK&&data!=null){Object returnedPosition=data.getExtras()==null?null:data.getExtras().get("position");if(!(returnedPosition instanceof Number)&&data.getExtras()!=null)returnedPosition=data.getExtras().get("extra_position");long position=returnedPosition instanceof Number?((Number)returnedPosition).longValue():-1;if(position>=0)getIntent().putExtra("position",position);}scheduleReturn();}}
 private void resumeStream(){if(!returning.finish())return;ExternalOutputState.end(sessionToken);getSharedPreferences("external_player",0).edit().clear().apply();handler.removeCallbacks(returned);Intent target=getIntent();if(!target.getBooleanExtra("sourceStopped",false)||BluetoothOutputButton.streamPlaying()||CastPlayback.hasMedia(this)&&CastPlayback.remote(this)!=null&&CastPlayback.remote(this).isPlaying()){finish();return;}String source=target.getStringExtra("source");long position=Math.max(0,target.getLongExtra("position",0));try{
   if("local".equals(source)){LocalMedia file=new LocalMedia(target.getStringExtra("uri"),target.getStringExtra("name"),target.getStringExtra("mime"),false);Player existing=LocalAudioService.player();LocalMedia selected=LocalAudioService.current();if(existing!=null&&selected!=null&&selected.uri.equals(file.uri)){existing.seekTo(position);if(existing.getPlaybackState()==Player.STATE_IDLE)existing.prepare();existing.play();}else{List<LocalMedia> queue=LocalAudioService.queue();androidx.core.content.ContextCompat.startForegroundService(this,LocalAudioService.playIntent(this,file,queue.isEmpty()?Collections.singletonList(file):queue).putExtra("position",position));}}
   else if("carfile".equals(source)){Player current=RadioPlaybackService.audioPlayer();if(current!=null){current.seekTo(position);current.play();}else{LocalMedia file=new LocalMedia(target.getStringExtra("uri"),target.getStringExtra("name"),target.getStringExtra("mime"),false);androidx.core.content.ContextCompat.startForegroundService(this,LocalAudioService.playIntent(this,file).putExtra("position",position));}}
   else if("radio".equals(source)){RadioStation station=RadioStation.fromJson(new org.json.JSONObject(target.getStringExtra("radio")));androidx.core.content.ContextCompat.startForegroundService(this,RadioPlaybackService.playIntent(this,station));}
   else if("cast".equals(source)){var remote=CastPlayback.remote(this);com.google.android.gms.cast.MediaInfo info=target.getParcelableExtra("castInfo");if(remote!=null&&info!=null){com.google.android.gms.cast.MediaLoadRequestData.Builder request=new com.google.android.gms.cast.MediaLoadRequestData.Builder().setMediaInfo(info).setAutoplay(true);if(!target.getBooleanExtra("live",false))request.setCurrentTime(position);remote.load(request.build());}}
   else if("video".equals(source)){Intent resume=new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("resumeCastUrl",target.getStringExtra("uri")).putExtra("resumeCastName",target.getStringExtra("name")).putExtra("resumeCastKind",target.getStringExtra("kind")).putExtra("resumeCastLogo",target.getStringExtra("logo")).putExtra("resumeCastPosition",position);startActivity(resume);}
  }catch(Exception error){android.widget.Toast.makeText(this,"Afspilningen kunne ikke genoptages. Vælg den igen i Stream.",android.widget.Toast.LENGTH_LONG).show();}finish();}
 @Override protected void onSaveInstanceState(Bundle saved){saved.putBoolean("launched",returning.launched);saved.putBoolean("left",returning.left);super.onSaveInstanceState(saved);}
 @Override protected void onDestroy(){if(isFinishing())ExternalOutputState.end(sessionToken);handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
